mapper.select:
select , sg.remark, sg.createuser, sg.createtime, sg.updateuser, sg.updatetime, l.title, l.subtitle from u_s_sitegoods sg left join u_s_sitegoods_lang l on l.shop_code = sg.shop_code and l.sitecode = sg.sitecode and l.goodscode = sg.goodscode and l.lang = #{lang}
and sg.sitecode =
and sg.publishstatus = #{publishStatus}
and sg.sitecategory = #{category}
and (sg.goodscode like concat('%', #{keyword}, '%') or sg.goodsname like concat('%', #{keyword}, '%') or l.title like concat('%', #{keyword}, '%'))
order by sg.sortnum asc, sg.createtime desc, sg.goodscode asc
